for n,m in masks.items():
 ys,xs=np.where(m); print(n,len(xs),'bbox', [xs.min(),ys.min(),xs.max(),ys.max()] if len(xs) else '')
 for y in range(0,144,2):
  if m[y].sum()>0: print(y,','.join(str(x) for x in np.where(m[y])[0]))
 if n=='dark':break
